 public override void _Ready(){try{Vector3 a=new(0,0,0),b=new(1,0,0),c=new(0,1,0);C(ProjectileImpactSurface.Triangle(new(.25f,.25f,3),new(0,0,-1),a,b,c,out float t)&&Mathf.Abs(t-3)<1e-5,"front surface world t");C(ProjectileImpactSurface.Triangle(new(.25f,.25f,3),new(0,0,-1),a,c,b,out t)&&Mathf.Abs(t-3)<1e-5,"mirrored winding two-sided");C(!ProjectileImpactSurface.Triangle(new(2,2,3),new(0,0,-1),a,b,c,out _),"outside no invented hit");C(!ProjectileImpactSurface.Triangle(new(.25f,.25f,3),new(1,0,0),a,b,c,out _),"parallel rejects");C(!ProjectileImpactSurface.Triangle(new(.25f,.25f,-3),new(0,0,-1),a,b,c,out _),"behind ray rejects");var tr=new Transform3D(Basis.FromScale(new(-2,.5f,1.5f)),Vector3.Zero);var inv=tr.AffineInverse();var origin=new Vector3(-.5f,.125f,3);var dir=new Vector3(0,0,-1);C(ProjectileImpactSurface.Triangle(inv*origin,inv.Basis*dir,a,b,c,out t)&&Mathf.Abs(t-3)<1e-5,"nonuniform mirrored inverse keeps world-metres parameter");C((tr*(inv*origin+(inv.Basis*dir)*t)).DistanceTo(new(-.5f,.125f,0))<1e-5,"world local bary point consistency");var wall=new Wall(0,0,1,1);C(ProjectileImpactSurface.CrossesWall(new(-1,.5f),new(2,.5f),wall),"physical to visual crosses actual wall");C(!ProjectileImpactSurface.CrossesWall(new(-1,2),new(2,2),wall),"clear displacement");C(ProjectileImpactSurface.CrossesWall(new(.5f,.5f),new(.5f,.5f),wall),"inside conservative");C(!ProjectileImpactSurface.CrossesWall(new(-1,-1),new(-1,-1),wall),"outside zero segment");C(ProjectileImpactSurface.TriangleBudget==4096&&ProjectileImpactSurface.CandidateBudget==2&&ProjectileImpactSurface.CacheCapacity==8,"hard bounds declared");GD.Print($"PROJECTILE_SURFACE_MATH_PASS {checks}");done=true;}catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
